function copyField(value,label){const wrap=el('div',undefined,'copy-field'),input=el('input');input.value=value||'';input.readOnly=true;input.setAttribute('aria-label',label);wrap.append(input,copyButton(()=>input.value,label));return wrap;}
function copyButton(value,label){const b=el('button','⧉','copy-button');b.type='button';b.title=label+' kopieren';b.setAttribute('aria-label',label+' kopieren');b.onclick=async()=>{try{const text=value();if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const t=el('textarea');t.value=text;document.body.append(t);t.select();if(!document.execCommand('copy'))throw Error('Kopieren nicht verfügbar.');t.remove();}b.textContent='✓';setTimeout(()=>b.textContent='⧉',1400);}catch(e){message(e);}};return b;}
function enhanceCopies(){document.querySelectorAll('[data-copy]').forEach(input=>{if(input.parentElement.classList.contains('copy-field'))return;const wrap=el('div',undefined,'copy-field');input.before(wrap);wrap.append(input,copyButton(()=>input.value,input.closest('label')?.firstChild.textContent.trim()||'Wert'));});}
function licenseEligible(l,provider,projectName=null,sourceId=null,globalOnly=false){return (!provider||l.provider===provider)&&(!globalOnly||!l.project)&&(!l.source||!sourceId||l.source===sourceId)&&(projectName===null||!l.project||l.project===projectName);}
function licenseOptions(select,provider,value='',projectName=null,sourceId=null,globalOnly=false){select.replaceChildren();option(select,'','Ohne Lizenz / kostenlos');const found=licenses.filter(l=>licenseEligible(l,provider,projectName,sourceId,globalOnly));found.forEach(l=>option(select,l.id,l.label+' · '+(l.project||'Global')));select.value=found.some(l=>l.id===value)?value:'';}
function preferredLicense(source,projectName,explicit=''){const eligible=licenses.filter(l=>licenseEligible(l,source.provider,projectName,source.id));if(explicit&&eligible.some(l=>l.id===explicit))return explicit;return eligible.find(l=>l.project===projectName&&l.source===source.id)?.id||eligible.find(l=>l.project===projectName)?.id||(eligible.some(l=>l.id===source.license)?source.license:'');}
