async function route(){let [next,tab]=location.hash.replace(/^#\/?/,'').split('/');if(!titles[next])next='projects';view=next;document.querySelectorAll('aside nav button').forEach(n=>{n.classList.toggle('active',n.dataset.view===view);if(n.dataset.view===view)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});document.querySelectorAll('.view').forEach(n=>n.hidden=n.id!==view+'-view');$('#title').textContent=titles[view][0];$('#new').hidden=view!=='projects';if(tabDefaults[view])activateTab(view,tab||tabDefaults[view]);if(view==='extensions')renderExtensions();if(view==='activity')renderJobs();if(view==='system'){const values=await api('system-credentials');$('#system-credentials').replaceChildren(...Object.entries(values).map(([key,value])=>{const label=el('label',key);label.append(copyField(value,key));return label;}));const h=await api('health');$('#health').replaceChildren(el('p',h.docker?'● Docker erreichbar':'○ Docker nicht erreichbar'),el('p',h.kickstart?'● Akeeba Kickstart vorhanden':'● Kickstart wird beim Import automatisch geladen'));const box=$('#ports');box.replaceChildren();for(const php of phpVersions){const row=el('div',undefined,'row');row.append(el('strong','PHP '+php),el('span','HTTP 80'+php.replace('.','')+' · HTTPS 81'+php.replace('.','')));box.append(row);}}await refresh();if(view==='projects')renderProjects();window.scrollTo({top:0,behavior:'instant'});}
