$('#users-reset').onclick=()=>{$('#users-form').reset();$('#users-form').elements.id.value='';$('#users-form-title').textContent='Benutzer hinzufügen';};$('#users-close').onclick=()=>$('#users-dialog').close();$('#users-form').onsubmit=e=>{e.preventDefault();act(async()=>{const body=Object.fromEntries(new FormData(e.target));body.action=body.id?'reset':'create';await api('projects/'+userProject+'/users',body);await openUsers(userProject);await loadProjectUsers(userProject);message('CMS-Benutzer gespeichert. Zugangsdaten wurden im Projekt hinterlegt.');});};
async function scanLicenseKeys(name){const result=await api('projects/'+name+'/license-scan',{});$('#detail-content').replaceChildren(el('h2','Erkannte Lizenzschlüssel · '+name),el('p','Aus der wiederhergestellten CMS-Datenbank. Kontopasswörter und gehashte Benutzerpasswörter werden nicht importiert.'));for(const item of result.candidates){const row=el('div',undefined,'license-entry'),parent=el('select');parent.setAttribute('aria-label','Hauptlizenz für '+item.label);option(parent,'','Automatisch / neue Hauptlizenz');licenses.filter(l=>!l.parent&&!l.project&&l.provider===item.provider).forEach(l=>option(parent,l.id,l.label));row.append(el('strong',item.label),copyField(item.key,item.label),parent,button('Als Seitenschlüssel speichern',()=>api('projects/'+name+'/license-import',{candidate:item,parent:parent.value})));$('#detail-content').append(row);}if(!result.candidates.length)$('#detail-content').append(el('p','Keine unterstützten Lizenzschlüssel erkannt.'));$('#detail').showModal();}

let kickstartVersions=[];
async function loadKickstart(){const data=await api('kickstart');kickstartVersions=data.versions;for(const id of ['#project-kickstart','#retry-kickstart']){const select=$(id),old=select.value;select.replaceChildren();option(select,'auto','Automatisch · neueste Version');for(const x of data.versions)option(select,x.version,'Kickstart '+x.version);if(data.manual)option(select,'manual','Eigene hinterlegte kickstart.php');if([...select.options].some(o=>o.value===old))select.value=old;}const box=$('#kickstart-versions');box.replaceChildren();if(!data.versions.length)empty(box,'Die aktuelle Version wird beim ersten Import automatisch geladen. Für eine bestimmte Version zuerst den Katalog abrufen.');else{const select=el('select');select.setAttribute('aria-label','Kickstart-Version herunterladen');for(const x of data.versions)option(select,x.version,'Kickstart '+x.version);box.append(select,button('Version herunterladen',()=>api('kickstart/download',{version:select.value})));}}
$('#kickstart-sync').onclick=()=>act(()=>api('kickstart/sync',{}));
function openRetry(p){const f=$('#retry-restore-form');f.reset();f.dataset.project=p.slug;const select=$('#retry-backup');select.replaceChildren();for(const b of backups)for(const file of b.files.filter(n=>/\.(jpa|jps|zip)$/i.test(n)))option(select,b.id+'/'+file,file);select.value=(p.backup_group||'')+'/'+(p.backup_archive||'');if(p.restore_phase==='extracted')select.disabled=true;else select.disabled=false;loadKickstart().then(()=>{$('#retry-kickstart').value=p.kickstart||'auto';}).catch(message);$('#retry-restore').showModal();}
let updateInstalling=false;
async function renderManagerUpdate(){const data=await api('manager-update'),box=$('#manager-update'),notice=$('#update-notice');box.replaceChildren(el('p','Installierte Version: '+data.current),projectLink(data.source,'GitHub-Releases ↗'));if(data.checked)box.append(el('p','Letzte Prüfung: '+new Date(data.checked*1000).toLocaleString('de-DE')));if(data.error)box.append(el('p',data.error,'small-note'));const installation=data.installation;updateInstalling=installation&&['queued','running'].includes(installation.status);if(installation)box.append(el('p',installation.message,installation.status==='error'?'error':'small-note'));if(data.available&&!data.error){const install=button('Update '+data.latest+' installieren',async()=>{await api('manager-update/install',{version:data.latest});message('Update gestartet. Der Manager startet neu und verbindet sich anschließend automatisch.');updateInstalling=true;});install.disabled=updateInstalling||jobActive('manager-update');box.append(install);notice.hidden=false;notice.replaceChildren(el('span','Manager-Update '+data.latest+' verfügbar. '));const link=el('a','Update öffnen');link.href='#system/updates';notice.append(link);}else notice.hidden=true;}
$('#manager-check').onclick=()=>act(()=>api('manager-update/check',{}));
renderManagerUpdate().catch(()=>{});setInterval(()=>{if(view!=='system')renderManagerUpdate().catch(()=>{});},60000);

async function loadDatabaseProfiles(){const data=await api('database-profiles'),select=$('#project-database-profile'),previous=select.value;select.replaceChildren();option(select,'auto','Automatisch nach Projektanforderungen');for(const item of data.profiles)option(select,item.id,(item.engine==='mysql'?'MySQL':'MariaDB')+' '+item.version);select.value=previous||'auto';}
async function renderEnvironment(){const value=await api('environment'),box=$('#environment-report');box.replaceChildren();if(value.status==='unknown'){empty(box,value.message);return;}box.append(el('h3','Installationsprüfung'),el('p',value.status==='ok'?'Umgebung geprüft':'Umgebung benötigt Aufmerksamkeit'));for(const [key,label] of [['docker_version','Docker'],['architecture','Prozessorarchitektur'],['compose','Compose'],['context','Docker-Kontext']])if(value[key])box.append(el('p',label+': '+value[key]));if(value.existing_database){const d=value.existing_database;box.append(el('p','Bestehendes Datenbankprofil: '+d.engine+' '+d.version+' · bleibt erhalten'));}if(value.message)box.append(el('p',value.message,'error'));for(const warning of value.warnings||[])box.append(el('p',warning,'small-note'));}
$('#environment-check').onclick=()=>act(()=>api('environment/check',{}));
